[[nodiscard]] static const CompressedSourceCode *get_source_code(std::string_view name) {
  if (name == "api")
    return &api;
  if (name == "anno")
    return &anno;
  if (name == "debug")
    return &debug;
  if (name == "df")
    return &df;
  if (name == "limits")
    return &limits;
  if (name == "math")
    return &math;
  if (name == "scene")
    return &scene;
  if (name == "state")
    return &state;
  if (name == "std")
    return &std;
  if (name == "tex")
    return &tex;
  if (name == "extras::io")
    return &extras_io;
  if (name == "extras::lod")
    return &extras_lod;
  if (name == "extras::noise")
    return &extras_noise;
  if (name == "extras::parallax")
    return &extras_parallax;
  if (name == "extras::sampling")
    return &extras_sampling;
  if (name == "extras::tiling")
    return &extras_tiling;
  if (name == "models::illuminant")
    return &models_illuminant;
  if (name == "models::marmit")
    return &models_marmit;
  if (name == "models::metal_ior")
    return &models_metal_ior;
  if (name == "models::optical_glass")
    return &models_optical_glass;
  if (name == "models::prospect")
    return &models_prospect;
  if (name == "models::regolith")
    return &models_regolith;
  if (name == "models::woody")
    return &models_woody;
  return nullptr;
}
